import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { parse } from 'yaml';

// For every eval case with a reference solution (test/fixtures/eval-reference/<case>, generated by
// scripts/gen-eval-fixture.ts), the file-based graders must accept the solution and reject the untouched start
// state. This checks the graders themselves without spending a model run. LLM and trace graders are skipped.
const EVALS = path.resolve(import.meta.dirname, '../../../plugins/defold/evals');
const REFERENCES = path.resolve(import.meta.dirname, '../fixtures/eval-reference');

type Files = Map<string, string>;

function overlay(files: Files, dir: string): void {
  const walk = (d: string) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else files.set(path.relative(dir, p).split(path.sep).join('/'), fs.readFileSync(p, 'latin1'));
    }
  };
  walk(dir);
}

/** The workspace a case starts from: basic plus the fixture overlays its scaffold.sh copies, in order. */
function startState(caseDir: string): Files {
  const files: Files = new Map();
  const scaffold = fs.readFileSync(path.join(caseDir, 'scaffold.sh'), 'utf8');
  for (const m of scaffold.matchAll(/_fixtures\/([\w-]+)\/\./g)) overlay(files, path.join(EVALS, '_fixtures', m[1]!));
  return files;
}

interface Grader {
  name: string;
  type: string;
  target?: { source?: string; path?: string } | string;
  path?: string;
  pattern?: string;
  flags?: string;
  match?: string;
}

function graders(caseDir: string): Grader[] {
  const dir = path.join(caseDir, 'graders');
  return fs.readdirSync(dir).map((f) => {
    const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(fs.readFileSync(path.join(dir, f), 'utf8'))![1]!;
    return { name: f, ...(parse(fm) as Omit<Grader, 'name'>) };
  });
}

/** Same semantics as `claude plugin eval` regex graders: contains | not_contains | count:N. */
function evaluate(g: Grader, files: Files): boolean | undefined {
  if (g.type === 'file_exists' && g.path && !/[*?]/.test(g.path)) return files.has(g.path);
  if (g.type !== 'regex' || typeof g.target !== 'object' || g.target.source !== 'file') return undefined;
  const text = files.get(g.target.path ?? '');
  const match = g.match ?? 'contains';
  if (text === undefined) return match === 'not_contains';
  const re = new RegExp(g.pattern!, g.flags ?? '');
  if (match === 'contains') return re.test(text);
  if (match === 'not_contains') return !re.test(text);
  if (match.startsWith('count:')) return [...text.matchAll(new RegExp(g.pattern!, `${g.flags ?? ''}g`))].length === Number(match.slice(6));
  throw new Error(`unknown match mode ${match}`);
}

const cases = fs.existsSync(REFERENCES) ? fs.readdirSync(REFERENCES) : [];

describe('eval graders against reference solutions', () => {
  it('has reference solutions to check', () => expect(cases.length).toBeGreaterThan(0));

  it.each(cases)('%s: graders accept the reference and reject the start state', (name) => {
    const caseDir = path.join(EVALS, name);
    const start = startState(caseDir);
    const solved = new Map(start);
    overlay(solved, path.join(REFERENCES, name));
    const checked = graders(caseDir).filter((g) => evaluate(g, start) !== undefined);
    expect(checked.length).toBeGreaterThan(0);
    const failedOnReference = checked.filter((g) => !evaluate(g, solved)).map((g) => g.name);
    expect(failedOnReference).toEqual([]);
    const failedOnStart = checked.filter((g) => !evaluate(g, start)).map((g) => g.name);
    expect(failedOnStart.length).toBeGreaterThan(0);
  });
});
